create schema if not exists private;
revoke all on schema private from public, anon;
grant usage on schema private to authenticated, service_role;
create table public.organizations(id uuid primary key default gen_random_uuid(), name text not null, timezone text not null default 'Asia/Jakarta');
insert into public.organizations(id,name) values ('6e143c55-7be5-4e6e-9f1a-8f8db429956a','EDUTARA CBT');
create table public.profiles(id uuid primary key references auth.users(id), organization_id uuid not null references public.organizations(id), username text not null unique check(username=lower(username) and username ~ '^[a-z0-9][a-z0-9_.-]{2,63}$'), full_name text not null check(length(full_name) between 1 and 150), role text not null check(role in ('admin','teacher','supervisor','student')), active boolean not null default true, archived_at timestamptz, created_at timestamptz not null default now(), unique(organization_id,id), check(archived_at is null or not active));
create table public.classes(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), name text not null check(length(trim(name)) between 1 and 100), active boolean not null default true, unique(organization_id,id));
create unique index classes_name_unique on public.classes(organization_id,lower(trim(name)));
create table public.subjects(like public.classes including all);
alter table public.subjects add foreign key(organization_id) references public.organizations(id);
create table public.teacher_assignments(id uuid primary key default gen_random_uuid(),organization_id uuid not null,teacher_id uuid not null,class_id uuid not null,subject_id uuid not null,active boolean not null default true,foreign key(organization_id,teacher_id) references public.profiles(organization_id,id),foreign key(organization_id,class_id) references public.classes(organization_id,id),foreign key(organization_id,subject_id) references public.subjects(organization_id,id),unique(teacher_id,class_id,subject_id));
create table public.student_enrollments(id uuid primary key default gen_random_uuid(),organization_id uuid not null,student_id uuid not null,class_id uuid not null,active boolean not null default true,foreign key(organization_id,student_id) references public.profiles(organization_id,id),foreign key(organization_id,class_id) references public.classes(organization_id,id),unique(student_id,class_id));
create table public.exams(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),subject_id uuid, title text not null,starts_at timestamptz not null,ends_at timestamptz not null,duration_minutes integer not null check(duration_minutes>0),pin_hash text not null,status text not null default 'draft' check(status in ('draft','scheduled','active','closed','archived')),passing_grade numeric not null default 0 check(passing_grade between 0 and 100),policy_version integer not null default 1 check(policy_version>0),unique(organization_id,id),foreign key(organization_id,subject_id) references public.subjects(organization_id,id),check(ends_at>starts_at));
create table public.exam_classes(organization_id uuid not null,exam_id uuid not null,class_id uuid not null, primary key(exam_id,class_id),foreign key(organization_id,exam_id) references public.exams(organization_id,id),foreign key(organization_id,class_id) references public.classes(organization_id,id));
create table public.exam_type_configs(exam_id uuid not null references public.exams(id),type text not null check(type in ('PG','PG_KOMPLEKS','BS','JODOH','Esai')),enabled boolean not null default true,max_questions integer check(max_questions>=0),option_count integer check(option_count between 2 and 6),default_points numeric not null check(default_points>0),primary key(exam_id,type));
create table public.questions(id uuid primary key default gen_random_uuid(),organization_id uuid not null,exam_id uuid not null,type text not null check(type in ('PG','PG_KOMPLEKS','BS','JODOH','Esai')),points numeric not null check(points>0),current_version integer not null default 1 check(current_version>0),archived_at timestamptz,foreign key(organization_id,exam_id) references public.exams(organization_id,id),unique(organization_id,id));
create table public.question_versions(question_id uuid not null references public.questions(id),version integer not null check(version>0),schema_version integer not null default 1 check(schema_version=1),payload jsonb not null check(jsonb_typeof(payload)='object'),created_at timestamptz not null default now(),primary key(question_id,version));
create table public.exam_attempts(id uuid primary key default gen_random_uuid(),organization_id uuid not null,exam_id uuid not null,student_id uuid not null,attempt_number integer not null default 1 check(attempt_number>0),status text not null default 'in_progress' check(status in ('in_progress','submitted','time_expired','disqualified','graded','reset')),started_at timestamptz not null default now(),deadline_at timestamptz not null,score_percent numeric check(score_percent between 0 and 100),version integer not null default 1,foreign key(organization_id,exam_id) references public.exams(organization_id,id),foreign key(organization_id,student_id) references public.profiles(organization_id,id),unique(exam_id,student_id,attempt_number),unique(organization_id,id),check(deadline_at>=started_at));
create unique index single_active_attempt on public.exam_attempts(exam_id,student_id) where status in ('in_progress','disqualified');
create table public.attempt_answers(attempt_id uuid not null references public.exam_attempts(id),question_id uuid not null,question_version integer not null,value jsonb not null,revision integer not null check(revision>0),saved_at timestamptz not null default now(),primary key(attempt_id,question_id),foreign key(question_id,question_version) references public.question_versions(question_id,version));
create table public.grade_items(id uuid primary key default gen_random_uuid(),attempt_id uuid not null references public.exam_attempts(id),question_id uuid not null,question_version integer not null,source text not null check(source in ('auto','manual','ai_suggestion')),awarded_points numeric not null,max_points numeric not null check(max_points>0),approved_by uuid references public.profiles(id),foreign key(question_id,question_version) references public.question_versions(question_id,version),check(awarded_points between 0 and max_points));
create table public.exam_rooms(id uuid primary key default gen_random_uuid(),organization_id uuid not null,exam_id uuid not null,name text not null,capacity integer not null check(capacity>=0),foreign key(organization_id,exam_id) references public.exams(organization_id,id),unique(organization_id,id),unique(organization_id,exam_id,id),unique(exam_id,name));
create table public.exam_room_students(organization_id uuid not null,exam_id uuid not null,room_id uuid not null,student_id uuid not null,primary key(exam_id,student_id),foreign key(organization_id,exam_id,room_id) references public.exam_rooms(organization_id,exam_id,id),foreign key(organization_id,student_id) references public.profiles(organization_id,id));
create table public.supervisor_assignments(id uuid primary key default gen_random_uuid(),organization_id uuid not null,exam_id uuid not null,room_id uuid not null,original_supervisor_id uuid not null,active boolean not null default true,foreign key(organization_id,exam_id,room_id) references public.exam_rooms(organization_id,exam_id,id),foreign key(organization_id,original_supervisor_id) references public.profiles(organization_id,id));
create table public.supervisor_substitutions(id uuid primary key default gen_random_uuid(),assignment_id uuid not null references public.supervisor_assignments(id),substitute_supervisor_id uuid not null references public.profiles(id),effective_from timestamptz not null default now(),effective_until timestamptz,revoked_at timestamptz,check(effective_until is null or effective_until>effective_from));
create unique index single_substitute on public.supervisor_substitutions(assignment_id) where revoked_at is null;
create table public.media_assets(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),uploader_id uuid not null references public.profiles(id),object_path text not null unique,mime_type text not null,byte_size bigint not null check(byte_size between 1 and 5242880),created_at timestamptz not null default now());
create table public.job_runs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),kind text not null,idempotency_key text not null,status text not null check(status in ('pending','running','completed','failed')),created_at timestamptz not null default now(),unique(organization_id,kind,idempotency_key));
create table public.audit_logs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),actor_id uuid,action text not null,target_type text not null,target_id text,request_id uuid,created_at timestamptz not null default now());
create table private.login_budgets(key text primary key,attempts integer not null,window_start timestamptz not null);
alter table private.login_budgets enable row level security;
create or replace function private.actor_org() returns uuid language sql stable security definer set search_path='' as $$ select p.organization_id from public.profiles p where p.id=auth.uid() and p.active and p.archived_at is null and exists(select 1 from auth.sessions s where s.id::text=auth.jwt()->>'session_id' and s.user_id=p.id) $$;
create or replace function private.is_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin' and p.organization_id=private.actor_org()) $$;
create or replace function private.teacher_student(target uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.profiles p join public.teacher_assignments t on t.teacher_id=p.id join public.student_enrollments e on e.class_id=t.class_id and e.organization_id=t.organization_id where p.id=auth.uid() and p.role='teacher' and t.active and e.active and e.student_id=target and p.organization_id=private.actor_org()) $$;
create or replace function public.has_supervisor_context() returns boolean language sql stable security definer set search_path='' as $$ select private.actor_org() is not null and exists(select 1 from public.supervisor_assignments a left join public.supervisor_substitutions s on s.assignment_id=a.id and s.revoked_at is null and s.effective_from<=now() and (s.effective_until is null or s.effective_until>now()) where a.active and a.organization_id=private.actor_org() and coalesce(s.substitute_supervisor_id,a.original_supervisor_id)=auth.uid()) $$;
create or replace function public.consume_login_budget(budget_key text) returns boolean language plpgsql security invoker set search_path='' as $$ declare n integer; begin insert into private.login_budgets values(budget_key,1,now()) on conflict(key) do update set attempts=case when private.login_budgets.window_start<now()-interval '15 minutes' then 1 else private.login_budgets.attempts+1 end,window_start=case when private.login_budgets.window_start<now()-interval '15 minutes' then now() else private.login_budgets.window_start end returning attempts into n; return n<=10; end $$;
revoke all on function private.actor_org(),private.is_admin(),private.teacher_student(uuid) from public,anon;
grant execute on function private.actor_org(),private.is_admin(),private.teacher_student(uuid) to authenticated;
revoke all on function public.has_supervisor_context() from public,anon;
grant execute on function public.has_supervisor_context() to authenticated;
revoke all on function public.consume_login_budget(text) from public,anon,authenticated;
grant execute on function public.consume_login_budget(text) to service_role;
grant all on private.login_budgets to service_role;
create or replace function private.audit_change() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.audit_logs(organization_id,actor_id,action,target_type,target_id) values(coalesce(new.organization_id,old.organization_id),auth.uid(),tg_op,tg_table_name,coalesce(new.id,old.id)::text); return coalesce(new,old); end $$;
revoke all on function private.audit_change() from public,anon,authenticated;
create or replace function private.protect_last_admin() returns trigger language plpgsql security definer set search_path='' as $$ begin perform pg_advisory_xact_lock(hashtext('edutara-admin')); if old.role='admin' and old.active and (new.role<>'admin' or not new.active) and not exists(select 1 from public.profiles where organization_id=old.organization_id and id<>old.id and role='admin' and active) then raise exception 'Last active admin cannot be deactivated'; end if; return new; end $$;
revoke all on function private.protect_last_admin() from public,anon,authenticated;
create trigger keep_admin before update on public.profiles for each row execute function private.protect_last_admin();
create or replace function private.room_capacity() returns trigger language plpgsql security definer set search_path='' as $$ declare cap integer; begin select capacity into cap from public.exam_rooms where id=new.room_id for update; if (select count(*) from public.exam_room_students where room_id=new.room_id)>=cap then raise exception 'Room capacity exceeded'; end if; return new; end $$;
revoke all on function private.room_capacity() from public,anon,authenticated;
create trigger check_room_capacity before insert on public.exam_room_students for each row execute function private.room_capacity();
-- No Data API access to exam content/keys/attempts is opened before dedicated domain services exist.
do $$ declare t text; begin foreach t in array array['organizations','profiles','classes','subjects','teacher_assignments','student_enrollments','exams','exam_classes','exam_type_configs','questions','question_versions','exam_attempts','attempt_answers','grade_items','exam_rooms','exam_room_students','supervisor_assignments','supervisor_substitutions','media_assets','job_runs','audit_logs'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on public.%I from anon,authenticated',t); end loop; end $$;
grant select on public.organizations,public.profiles,public.classes,public.subjects,public.teacher_assignments,public.student_enrollments,public.audit_logs,public.media_assets to authenticated;
grant insert,update on public.classes,public.subjects,public.teacher_assignments,public.student_enrollments to authenticated;
create policy org_read on public.organizations for select to authenticated using(id=private.actor_org());
create policy profiles_read on public.profiles for select to authenticated using(organization_id=private.actor_org() and (id=auth.uid() or private.is_admin() or (role='student' and private.teacher_student(id))));
create policy classes_read on public.classes for select to authenticated using(organization_id=private.actor_org() and (private.is_admin() or exists(select 1 from public.teacher_assignments t where t.teacher_id=auth.uid() and t.class_id=classes.id and t.active) or exists(select 1 from public.student_enrollments e where e.student_id=auth.uid() and e.class_id=classes.id and e.active)));
create policy subjects_read on public.subjects for select to authenticated using(organization_id=private.actor_org() and (private.is_admin() or exists(select 1 from public.teacher_assignments t where t.teacher_id=auth.uid() and t.subject_id=subjects.id and t.active)));
create policy teacher_assignments_read on public.teacher_assignments for select to authenticated using(organization_id=private.actor_org() and (private.is_admin() or teacher_id=auth.uid()));
create policy enrollments_read on public.student_enrollments for select to authenticated using(organization_id=private.actor_org() and (private.is_admin() or student_id=auth.uid() or private.teacher_student(student_id)));
create policy audit_read on public.audit_logs for select to authenticated using(organization_id=private.actor_org() and private.is_admin());
create policy media_read on public.media_assets for select to authenticated using(organization_id=private.actor_org() and (private.is_admin() or uploader_id=auth.uid()));
do $$ declare t text; begin foreach t in array array['classes','subjects','teacher_assignments','student_enrollments'] loop execute format('create policy admin_insert on public.%I for insert to authenticated with check(organization_id=private.actor_org() and private.is_admin())',t); execute format('create policy admin_update on public.%I for update to authenticated using(organization_id=private.actor_org() and private.is_admin()) with check(organization_id=private.actor_org() and private.is_admin())',t); end loop; foreach t in array array['profiles','classes','subjects','teacher_assignments','student_enrollments'] loop execute format('create trigger audit_mutation after insert or update or delete on public.%I for each row execute function private.audit_change()',t); end loop; end $$;
create index teacher_assignments_class on public.teacher_assignments(class_id,teacher_id) where active;
create index student_enrollments_class on public.student_enrollments(class_id,student_id) where active;
create index profiles_org_role on public.profiles(organization_id,role,active);
create index audit_logs_org_time on public.audit_logs(organization_id,created_at desc);
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('exam-media','exam-media',false,5242880,array['image/png','image/jpeg','image/webp','audio/mpeg','audio/ogg','audio/wav','application/pdf']);
create policy media_own_select on storage.objects for select to authenticated using(bucket_id='exam-media' and private.actor_org() is not null and (private.is_admin() or (storage.foldername(name))[1]=auth.uid()::text));
create policy media_own_insert on storage.objects for insert to authenticated with check(bucket_id='exam-media' and private.actor_org() is not null and (storage.foldername(name))[1]=auth.uid()::text);
create policy media_own_update on storage.objects for update to authenticated using(bucket_id='exam-media' and private.actor_org() is not null and (storage.foldername(name))[1]=auth.uid()::text) with check(bucket_id='exam-media' and private.actor_org() is not null and (storage.foldername(name))[1]=auth.uid()::text);
create policy media_own_delete on storage.objects for delete to authenticated using(bucket_id='exam-media' and private.actor_org() is not null and (private.is_admin() or (storage.foldername(name))[1]=auth.uid()::text));
